def transform(grid):
    """Mark a blank suffix that truncates an otherwise matching row pattern."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # A repeated row-pattern can have an incomplete copy: its prefix matches
    # another row, while the rest is background where the template continues
    # in one foreground color. Mark that missing continuation with 1.
    for r in range(h):
        for rr in range(h):
            if r == rr:
                continue
            prefix = 0
            while prefix < w and grid[r][prefix] == grid[rr][prefix]:
                prefix += 1
            if prefix == w or prefix < w // 2:
                continue
            missing = [c for c in range(prefix, w)
                       if grid[r][c] == bg and grid[rr][c] != bg]
            if not missing:
                continue
            template_colors = {grid[rr][c] for c in range(prefix, w)
                               if grid[rr][c] != bg}
            if len(template_colors) == 1 and all(
                    grid[r][c] == bg and grid[rr][c] in template_colors
                    for c in range(prefix, w)):
                for c in missing:
                    out[r][c] = 1
    return out
